        <div><dt className="inline">Discount: </dt><dd className="inline">-{formatUSD(pricing.discountCents)}</dd></div>
        <div><dt className="inline">Shipping: </dt><dd className="inline">{formatUSD(pricing.shippingCents)}</dd></div>
        <div><dt className="inline">Tax: </dt><dd className="inline">{formatUSD(pricing.taxCents)}</dd></div>
        <div className="font-bold"><dt className="inline">Total: </dt><dd className="inline">{formatUSD(pricing.totalCents)}</dd></div>
      </dl>
      <button disabled={isLoading || !canSubmit} onClick={onSubmit}>
        {isLoading ? 'Processing...' : 'Place Order'}
      </button>
    </section>
