```

##### 2. NestJS Refactoring: Decomposed Use-Case Orchestrator, Inventory Repository, Payment Gateway, and Domain Event Listener
```typescript
// src/orders/domain/order-pricing.domain-service.ts
import { Injectable, BadRequestException } from '@nestjs/common';

export interface OrderItemInput {
  sku: string;
  qty: number;
  priceCents: number;
}

@Injectable()
export class OrderPricingDomainService {
  calculateValidatedTotal(items: readonly OrderItemInput[]): number {
    if (!items || items.length === 0) {
      throw new BadRequestException('Order must contain at least one item');
    }
    for (const item of items) {
      if (item.qty <= 0 || item.priceCents < 0) {
        throw new BadRequestException(`Invalid quantity or price for SKU: ${item.sku}`);
      }
    }
    return items.reduce((sum, i) => sum + i.priceCents * i.qty, 0);
  }
}
```

```typescript
// src/orders/infrastructure/order-persistence.repository.ts
import { Injectable, BadRequestException } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { OrderItemInput } from '../domain/order-pricing.domain-service';

@Injectable()
export class OrderPersistenceRepository {
  constructor(private readonly dataSource: DataSource) {}

  async reserveStockAndCreatePendingOrder(
    userId: string,
    totalCents: number,
    items: readonly OrderItemInput[]
  ): Promise<string> {
    return this.dataSource.transaction(async (manager) => {
      for (const item of items) {
        const res = await manager.query(
          `UPDATE inventory SET stock = stock - $1 WHERE sku = $2 AND stock >= $1 RETURNING sku`,
          [item.qty, item.sku]
        );
        if (res.length === 0) {
          throw new BadRequestException(`Insufficient stock for SKU: ${item.sku}`);
        }
      }
      const orderRows = await manager.query(
        `INSERT INTO orders (user_id, total_cents, status) VALUES ($1, $2, 'PENDING') RETURNING id`,
        [userId, totalCents]
      );
      return orderRows[0].id as string;
    });
  }

  async markOrderPaid(orderId: string, externalPaymentId: string): Promise<void> {
    await this.dataSource.query(
      `UPDATE orders SET status = 'PAID', stripe_pi_id = $1 WHERE id = $2`,
      [externalPaymentId, orderId]
    );
  }

  async compensateFailedOrder(orderId: string, items: readonly OrderItemInput[]): Promise<void> {
    await this.dataSource.transaction(async (manager) => {
      for (const item of items) {
        await manager.query(`UPDATE inventory SET stock = stock + $1 WHERE sku = $2`, [item.qty, item.sku]);
      }
      await manager.query(`UPDATE orders SET status = 'PAYMENT_FAILED' WHERE id = $1`, [orderId]);
    });
  }
}
```

```typescript
// src/orders/application/place-order.use-case.ts
import { Injectable } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import { OrderPricingDomainService, OrderItemInput } from '../domain/order-pricing.domain-service';
import { OrderPersistenceRepository } from '../infrastructure/order-persistence.repository';
import { StripePaymentGateway } from '../infrastructure/stripe-payment.gateway';

export class OrderPaidEvent {
  constructor(
    public readonly orderId: string,
    public readonly userEmail: string,
    public readonly totalCents: number
  ) {}
}

@Injectable()
export class PlaceOrderUseCase {
  constructor(
    private readonly pricingService: OrderPricingDomainService,
    private readonly repository: OrderPersistenceRepository,
    private readonly paymentGateway: StripePaymentGateway,
    private readonly eventEmitter: EventEmitter2
  ) {}

  async execute(command: {
    userId: string;
    userEmail: string;
    items: OrderItemInput[];
    paymentMethodId: string;
  }): Promise<{ orderId: string; status: 'PAID' }> {
    const totalCents = this.pricingService.calculateValidatedTotal(command.items);

    // Phase 1: Fast local DB transaction (releases locks before external HTTP call)
    const orderId = await this.repository.reserveStockAndCreatePendingOrder(
      command.userId,
      totalCents,
      command.items
    );

    // Phase 2: External Payment Execution outside DB transaction
    try {
      const paymentResult = await this.paymentGateway.charge({
        orderId,
        amountCents: totalCents,
        paymentMethodId: command.paymentMethodId,
      });

      await this.repository.markOrderPaid(orderId, paymentResult.transactionId);
    } catch (paymentErr) {
      await this.repository.compensateFailedOrder(orderId, command.items);
      throw paymentErr;
    }

    // Phase 3: Decoupled Post-Commit Notification via Event
    this.eventEmitter.emit(
      'order.paid',
      new OrderPaidEvent(orderId, command.userEmail, totalCents)
    );

    return { orderId, status: 'PAID' };
  }
}
```

