@Injectable()
export class PaymentProcessorService {
  async processPayment(provider: 'STRIPE' | 'ADYEN' | 'PAYPAL', amountCents: number, metadata: any) {
    // Adding 'BRAINTREE' or 'KLARNA' requires modifying this tested core class
    switch (provider) {
      case 'STRIPE': {
        if (amountCents < 50) throw new BadRequestException('Stripe minimum is $0.50');
        // Direct Stripe API formatting & call
        return { provider: 'STRIPE', externalId: `pi_${Date.now()}`, fee: Math.round(amountCents * 0.029) + 30 };
      }
      case 'ADYEN': {
        if (!metadata.shopperReference) throw new BadRequestException('Adyen requires shopperReference');
        // Direct Adyen API formatting & call
        return { provider: 'ADYEN', externalId: `psp_${Date.now()}`, fee: Math.round(amountCents * 0.025) + 12 };
      }
      case 'PAYPAL': {
        if (amountCents > 1000000) throw new BadRequestException('PayPal cap exceeded');
        // Direct PayPal API formatting & call
        return { provider: 'PAYPAL', externalId: `pp_${Date.now()}`, fee: Math.round(amountCents * 0.034) + 49 };
      }
      default:
        throw new BadRequestException(`Unsupported payment provider: ${provider}`);
    }
  }
