// src/payments/payment-orchestrator.service.ts
// CLOSED FOR MODIFICATION: Orchestrator resolves strategies dynamically via O(1) Map lookup.
import { Injectable, Inject, BadRequestException } from '@nestjs/common';
import {
  PAYMENT_STRATEGIES,
  PaymentProviderStrategy,
  PaymentChargeRequest,
  PaymentChargeResult,
} from './contracts/payment-strategy.interface';

@Injectable()
export class PaymentOrchestratorService {
  private readonly strategyMap: ReadonlyMap<string, PaymentProviderStrategy>;

  constructor(
    @Inject(PAYMENT_STRATEGIES) strategies: readonly PaymentProviderStrategy[]
  ) {
    const map = new Map<string, PaymentProviderStrategy>();
    for (const strategy of strategies) {
      if (map.has(strategy.providerKey)) {
        throw new Error(`Duplicate PaymentProviderStrategy registered for key: ${strategy.providerKey}`);
      }
      map.set(strategy.providerKey, strategy);
    }
    this.strategyMap = map;
  }

  async processPayment(
    providerKey: string,
    request: PaymentChargeRequest
  ): Promise<PaymentChargeResult> {
    const strategy = this.strategyMap.get(providerKey);
    if (!strategy) {
      throw new BadRequestException(`Unsupported payment provider: ${providerKey}`);
    }
    return strategy.executeCharge(request);
  }
}
