  id: string;
  email: string;
  version: number;
}

export interface UserRepositoryPort {
  /**
   * Contract:
   * - Precondition: id is any non-empty string.
   * - Postcondition: Returns UserRecord if found, or `null` if no user exists. Never throws on missing user.
   */
  findById(id: string): Promise<UserRecord | null>;

  /**
   * Contract:
   * - Atomically increments `version` and persists user.
   * - Throws OptimisticLockError if current version does not match.
