import { Injectable, NotFoundException, NotImplementedException } from '@nestjs/common';
import { UserRepositoryPort, UserRecord } from '../contracts/user-repository.port';
import Redis from 'ioredis';

@Injectable()
export class BrokenRedisUserRepository implements UserRepositoryPort {
  constructor(private readonly redis: Redis) {}

  async findById(id: string): Promise<UserRecord | null> {
    // LSP VIOLATION 1 (Strengthened Precondition): Rejects non-UUID strings even though Port allows any non-empty string
    if (!/^[0-9a-fA-F-]{36}$/.test(id)) {
      throw new Error('Redis adapter requires strict 36-char UUID');
    }

    const raw = await this.redis.get(`user:${id}`);
    if (!raw) {
      // LSP VIOLATION 2 (Broken Postcondition / Exception Contract):
      // Port guarantees returning `null` on cache miss; this adapter throws NotFoundException!
      throw new NotFoundException(`User ${id} not found in Redis`);
    }
    return JSON.parse(raw);
  }

  async save(_user: UserRecord): Promise<UserRecord> {
    // LSP VIOLATION 3 (Refused Bequest): Read-only replica/cache throwing on interface method
    throw new NotImplementedException('Redis User Repository is read-only');
  }
