##### 2. NestJS Refactoring: Separating Read/Write Capabilities and Enforcing Contract Invariants
If an adapter is genuinely read-only, it must implement a `UserReaderPort` (combining ISP + LSP), not pretend to implement a full `UserRepositoryPort`. And for full repository implementations (e.g., `PostgresUserRepository` and `InMemoryUserRepository`), both must uphold identical precondition, postcondition, and optimistic concurrency semantics.

```typescript
// src/users/contracts/user-repository.port.ts
export class OptimisticLockError extends Error {
  constructor(public readonly userId: string, public readonly expectedVersion: number) {
    super(`Optimistic lock failure for user ${userId} at version ${expectedVersion}`);
    this.name = 'OptimisticLockError';
  }
}

export interface UserRecord {
  readonly id: string;
  readonly email: string;
  readonly version: number;
}

export const USER_REPOSITORY_PORT = Symbol('USER_REPOSITORY_PORT');

export interface UserRepositoryPort {
  findById(id: string): Promise<UserRecord | null>;
  save(user: UserRecord): Promise<UserRecord>;
}
```

```typescript
// src/users/infrastructure/in-memory-user.repository.ts
import { Injectable } from '@nestjs/common';
import { UserRepositoryPort, UserRecord, OptimisticLockError } from '../contracts/user-repository.port';

@Injectable()
export class InMemoryUserRepository implements UserRepositoryPort {
  private readonly store = new Map<string, UserRecord>();

  async findById(id: string): Promise<UserRecord | null> {
    if (!id || id.trim().length === 0) {
      throw new TypeError('User id must be a non-empty string');
    }
    return this.store.get(id) ?? null;
  }

  async save(user: UserRecord): Promise<UserRecord> {
    const existing = this.store.get(user.id);
    if (existing && existing.version !== user.version) {
      throw new OptimisticLockError(user.id, user.version);
    }
    const updated: UserRecord = {
      ...user,
      version: user.version + 1,
    };
    this.store.set(user.id, updated);
    return updated;
  }
}
```

```typescript
// src/users/infrastructure/postgres-user.repository.ts
import { Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { UserRepositoryPort, UserRecord, OptimisticLockError } from '../contracts/user-repository.port';

@Injectable()
export class PostgresUserRepository implements UserRepositoryPort {
  constructor(private readonly dataSource: DataSource) {}

  async findById(id: string): Promise<UserRecord | null> {
    if (!id || id.trim().length === 0) {
      throw new TypeError('User id must be a non-empty string');
    }
    const rows = await this.dataSource.query(
      `SELECT id, email, version FROM users WHERE id = $1 LIMIT 1`,
      [id]
    );
    return rows.length > 0 ? (rows[0] as UserRecord) : null;
  }

  async save(user: UserRecord): Promise<UserRecord> {
    const rows = await this.dataSource.query(
      `INSERT INTO users (id, email, version)
       VALUES ($1, $2, 1)
       ON CONFLICT (id) DO UPDATE
       SET email = EXCLUDED.email, version = users.version + 1
       WHERE users.version = $3
       RETURNING id, email, version`,
      [user.id, user.email, user.version]
    );

    if (rows.length === 0) {
      throw new OptimisticLockError(user.id, user.version);
    }
    return rows[0] as UserRecord;
  }
}
```

