import axios from 'axios'; // Direct low-level HTTP library dependency

export const InvoiceDownloadButton: React.FC<{ invoiceId: string }> = ({ invoiceId }) => {
  const [downloading, setDownloading] = useState(false);

  const handleDownload = async () => {
    setDownloading(true);
    try {
      // Directly coupled to browser localStorage token format and specific REST endpoint
      const token = window.localStorage.getItem('enterprise_auth_jwt');
      const response = await axios.get(`https://api.enterprise.com/v2/invoices/${invoiceId}/pdf`, {
        headers: { Authorization: `Bearer ${token}` },
