      link.href = url;
      link.setAttribute('download', `invoice-${invoiceId}.pdf`);
      document.body.appendChild(link);
      link.click();
      link.remove();
    } finally {
      setDownloading(false);
    }
  };

  return (
    <button disabled={downloading} onClick={handleDownload}>
      {downloading ? 'Generating PDF...' : 'Download Invoice'}
