        ContentType: 'application/json',
        ServerSideEncryption: 'aws:kms',
      })
    );

    await this.dataSource.query(
      `UPDATE invoices SET archived_s3_key = $1 WHERE id = $2`,
      [bucketKey, invoiceId]
    );

    return bucketKey;
  }
}
