```typescript
// src/invoices/application/invoice-archiver.use-case.ts
// High-Level Policy: Depends ONLY on domain-owned ports!
import { Injectable, Inject, NotFoundException } from '@nestjs/common';
import {
  INVOICE_REPOSITORY_PORT,
  BLOB_ARCHIVE_STORAGE_PORT,
  InvoiceRepositoryPort,
  BlobArchiveStoragePort,
} from '../domain/ports/invoice-archival.ports';

@Injectable()
export class InvoiceArchiverUseCase {
  constructor(
    @Inject(INVOICE_REPOSITORY_PORT) private readonly invoiceRepo: InvoiceRepositoryPort,
    @Inject(BLOB_ARCHIVE_STORAGE_PORT) private readonly blobStorage: BlobArchiveStoragePort
  ) {}

  async archiveInvoice(invoiceId: string): Promise<{ archiveKey: string }> {
    const invoice = await this.invoiceRepo.findById(invoiceId);
    if (!invoice) {
      throw new NotFoundException(`Invoice ${invoiceId} not found`);
    }

    // Pure domain naming policy for compliance archival
    const year = invoice.issuedAt.getUTCFullYear();
    const archiveKey = `archives/${year}/${invoice.id}.json`;

    await this.blobStorage.storeImmutableJson(archiveKey, {
      id: invoice.id,
      customerId: invoice.customerId,
      amountCents: invoice.amountCents,
      issuedAtIso: invoice.issuedAt.toISOString(),
    });

    await this.invoiceRepo.markArchived(invoice.id, archiveKey);
    return { archiveKey };
  }
}
