### 4.2 Identification of Concrete SOLID Violations in the Legacy System
```typescript
// LEGACY VIOLATING CODE: src/checkout/god-checkout.service.bad.ts
import { Injectable, BadRequestException } from '@nestjs/common';
import { DataSource } from 'typeorm';
import Stripe from 'stripe';
import * as nodemailer from 'nodemailer';

@Injectable()
export class GodCheckoutService {
  private stripe = new Stripe(process.env.STRIPE_KEY!, { apiVersion: '2023-10-16' });
  private mailer = nodemailer.createTransport({ host: process.env.SMTP_HOST });

  constructor(private readonly dataSource: DataSource) {}

  async checkout(dto: {
    userId: string;
    items: Array<{ productId: string; quantity: number }>;
    paymentProvider: 'STRIPE' | 'PAYPAL' | 'INTERNAL_CREDIT';
    paymentToken: string;
  }) {
    // [Violation 1 - SRP & DIP]: Directly querying User management table inside Checkout
    const users = await this.dataSource.query(`SELECT * FROM users WHERE id = $1`, [dto.userId]);
    if (!users[0] || users[0].is_suspended) {
      throw new BadRequestException('User account is suspended or missing');
    }
    const user = users[0];

    // [Violation 2 - SRP & DIP]: Directly querying Product Catalog & computing loyalty pricing
    let totalCents = 0;
    for (const item of dto.items) {
      const products = await this.dataSource.query(`SELECT * FROM products WHERE id = $1`, [item.productId]);
      if (!products[0]) throw new BadRequestException(`Product ${item.productId} not found`);
      totalCents += products[0].price_cents * item.quantity;
    }
    if (user.loyalty_tier === 'PLATINUM') {
      totalCents = Math.round(totalCents * 0.9); // 10% Platinum discount
    }

    // [Violation 3 - OCP]: Hardcoded switch statement for payment providers
    let externalTxId = '';
    if (dto.paymentProvider === 'STRIPE') {
      const pi = await this.stripe.paymentIntents.create({
        amount: totalCents,
        currency: 'usd',
        payment_method: dto.paymentToken,
        confirm: true,
      });
      externalTxId = pi.id;
    } else if (dto.paymentProvider === 'PAYPAL') {
      // PayPal HTTP call...
      externalTxId = `pp_${Date.now()}`;
    } else if (dto.paymentProvider === 'INTERNAL_CREDIT') {
      if (user.store_credit_cents < totalCents) throw new BadRequestException('Insufficient store credit');
      await this.dataSource.query(
        `UPDATE users SET store_credit_cents = store_credit_cents - $1 WHERE id = $2`,
        [totalCents, user.id]
      );
      externalTxId = `cred_${Date.now()}`;
    }

    // [Violation 4 - Consistency Hazard & SRP]: Decrementing inventory AFTER charging card without reservation!
    for (const item of dto.items) {
      const updated = await this.dataSource.query(
        `UPDATE inventory SET available = available - $1 WHERE product_id = $2 AND available >= $1 RETURNING product_id`,
        [item.quantity, item.productId]
      );
      if (updated.length === 0) {
        // Customer's card was ALREADY charged above, and now stock is gone!
        throw new BadRequestException('Out of stock after payment!');
      }
    }

    const orderRows = await this.dataSource.query(
      `INSERT INTO orders (user_id, total_cents, payment_tx_id, status) VALUES ($1, $2, $3, 'COMPLETED') RETURNING id`,
      [user.id, totalCents, externalTxId]
    );
    const orderId = orderRows[0].id;

    // [Violation 5 - SRP & Failure Isolation]: Synchronous SMTP call fails the whole HTTP response after payment!
    await this.mailer.sendMail({
      from: 'orders@shop.com',
      to: user.email,
      subject: `Order #${orderId}`,
      text: `Paid ${totalCents} cents.`,
    });

    return { orderId, totalCents, externalTxId };
  }
}
```

