### 4.3 Incremental Strangler Refactoring Strategy
Rewriting the entire system in a "Big Bang" branch is an architectural anti-pattern. Instead, we execute a **4-Phase Incremental Refactoring** while keeping `POST /checkout` operational on every commit:
1. **Phase 1 (DIP + ISP Boundary Extraction):** Define narrow outbound ports (`CustomerEligibilityPort`, `CatalogPricingPort`, `InventoryReservationPort`, `OrderRepositoryPort`) and wrap existing SQL queries behind adapters.
2. **Phase 2 (SRP Domain Extraction & Reservation Ordering Fix):** Extract pure `CheckoutPricingPolicy` and fix the execution sequence in `PlaceOrderUseCase` so inventory is reserved *before* charging the payment gateway, with compensating rollback on payment failure.
3. **Phase 3 (OCP Payment Strategy Registry):** Extract `STRIPE`, `PAYPAL`, and `INTERNAL_CREDIT` into independent `PaymentGatewayStrategy` implementations.
4. **Phase 4 (Asynchronous Notification Decoupling):** Replace synchronous `mailer.sendMail()` with an in-process/outbox `OrderCompletedEvent` handled by the `NotificationsModule`.

---

### 4.4 Revised Module Boundaries & Production TypeScript Implementations

#### 1. Segregated Cross-Module Ports (ISP & DIP)
```typescript
// src/checkout/domain/ports/checkout-dependencies.ports.ts
export const CUSTOMER_ELIGIBILITY_PORT = Symbol('CUSTOMER_ELIGIBILITY_PORT');
export const CATALOG_PRICING_PORT = Symbol('CATALOG_PRICING_PORT');
export const INVENTORY_RESERVATION_PORT = Symbol('INVENTORY_RESERVATION_PORT');
export const ORDER_REPOSITORY_PORT = Symbol('ORDER_REPOSITORY_PORT');
export const PAYMENT_STRATEGY_REGISTRY = Symbol('PAYMENT_STRATEGY_REGISTRY');

export type LoyaltyTier = 'STANDARD' | 'GOLD' | 'PLATINUM';

// ISP: Checkout only sees customer eligibility & tier, NOT password hashes or MFA secrets
export interface CustomerCheckoutProfile {
  readonly userId: string;
  readonly email: string;
  readonly isSuspended: boolean;
  readonly loyaltyTier: LoyaltyTier;
}

export interface CustomerEligibilityPort {
  getCheckoutProfile(userId: string): Promise<CustomerCheckoutProfile | null>;
}

// ISP: Checkout only needs current unit prices for requested product IDs
export interface CatalogPricingPort {
  getUnitPricesCents(productIds: readonly string[]): Promise<ReadonlyMap<string, number>>;
}

// LSP & DIP: Atomic stock reservation & release contract
export interface StockItemQuantity {
  readonly productId: string;
  readonly quantity: number;
}

export interface InventoryReservationPort {
  reserveStock(reservationId: string, items: readonly StockItemQuantity[]): Promise<boolean>;
  releaseReservation(reservationId: string, items: readonly StockItemQuantity[]): Promise<void>;
  commitReservation(reservationId: string): Promise<void>;
}

export interface PersistedOrderRecord {
  readonly orderId: string;
  readonly userId: string;
  readonly totalCents: number;
  readonly status: 'PENDING_PAYMENT' | 'COMPLETED' | 'FAILED';
  readonly paymentTxId: string | null;
}

export interface OrderRepositoryPort {
  createPendingOrder(userId: string, totalCents: number): Promise<PersistedOrderRecord>;
  markOrderCompleted(orderId: string, paymentTxId: string): Promise<void>;
  markOrderFailed(orderId: string, reason: string): Promise<void>;
}

// OCP + LSP Contract for Payment Providers
export interface PaymentExecutionRequest {
  readonly orderId: string;
  readonly userId: string;
  readonly amountCents: number;
  readonly paymentToken: string;
}

export interface PaymentExecutionResult {
  readonly providerKey: string;
  readonly transactionId: string;
}

export interface PaymentGatewayStrategy {
  readonly providerKey: string;
  charge(request: PaymentExecutionRequest): Promise<PaymentExecutionResult>;
}
```

#### 2. Pure Domain Pricing Policy (SRP)
```typescript
// src/checkout/domain/policies/checkout-pricing.policy.ts
import { LoyaltyTier, StockItemQuantity } from '../ports/checkout-dependencies.ports';

export class DomainValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'DomainValidationError';
  }
}

const LOYALTY_DISCOUNT_MULTIPLIERS: Readonly<Record<LoyaltyTier, number>> = {
  STANDARD: 1.0,
  GOLD: 0.95,
  PLATINUM: 0.90,
};

export class CheckoutPricingPolicy {
  calculateTotalCents(
    items: readonly StockItemQuantity[],
    unitPrices: ReadonlyMap<string, number>,
    tier: LoyaltyTier
  ): number {
    if (items.length === 0) {
      throw new DomainValidationError('Cannot checkout with an empty cart');
    }

    let rawSubtotalCents = 0;
    for (const item of items) {
      if (item.quantity <= 0) {
        throw new DomainValidationError(`Invalid quantity ${item.quantity} for product ${item.productId}`);
      }
      const unitPrice = unitPrices.get(item.productId);
      if (unitPrice === undefined) {
        throw new DomainValidationError(`Product ${item.productId} does not exist in catalog`);
      }
      rawSubtotalCents += unitPrice * item.quantity;
    }

    const multiplier = LOYALTY_DISCOUNT_MULTIPLIERS[tier];
    return Math.round(rawSubtotalCents * multiplier);
  }
}
