#### 3. Application Use-Case Orchestrator (SRP, OCP, DIP)
```typescript
// src/checkout/application/execute-checkout.use-case.ts
import { Injectable, Inject, BadRequestException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import {
  CUSTOMER_ELIGIBILITY_PORT,
  CATALOG_PRICING_PORT,
  INVENTORY_RESERVATION_PORT,
  ORDER_REPOSITORY_PORT,
  PAYMENT_STRATEGY_REGISTRY,
  CustomerEligibilityPort,
  CatalogPricingPort,
  InventoryReservationPort,
  OrderRepositoryPort,
  PaymentGatewayStrategy,
  StockItemQuantity,
} from '../domain/ports/checkout-dependencies.ports';
import { CheckoutPricingPolicy } from '../domain/policies/checkout-pricing.policy';

export class OrderCompletedDomainEvent {
  constructor(
    public readonly orderId: string,
    public readonly userId: string,
    public readonly userEmail: string,
    public readonly totalCents: number,
    public readonly transactionId: string
  ) {}
}

@Injectable()
export class ExecuteCheckoutUseCase {
  private readonly pricingPolicy = new CheckoutPricingPolicy();
  private readonly paymentStrategies: ReadonlyMap<string, PaymentGatewayStrategy>;

  constructor(
    @Inject(CUSTOMER_ELIGIBILITY_PORT) private readonly customers: CustomerEligibilityPort,
    @Inject(CATALOG_PRICING_PORT) private readonly catalog: CatalogPricingPort,
    @Inject(INVENTORY_RESERVATION_PORT) private readonly inventory: InventoryReservationPort,
    @Inject(ORDER_REPOSITORY_PORT) private readonly orders: OrderRepositoryPort,
    @Inject(PAYMENT_STRATEGY_REGISTRY) strategies: readonly PaymentGatewayStrategy[],
    private readonly eventBus: EventEmitter2
  ) {
    this.paymentStrategies = new Map(strategies.map((s) => [s.providerKey, s]));
  }

  async execute(command: {
    userId: string;
    items: readonly StockItemQuantity[];
    paymentProvider: string;
    paymentToken: string;
  }): Promise<{ orderId: string; totalCents: number; transactionId: string }> {
    const strategy = this.paymentStrategies.get(command.paymentProvider);
    if (!strategy) {
      throw new BadRequestException(`Unsupported payment provider: ${command.paymentProvider}`);
    }

    // 1. Verify Customer Eligibility
    const customer = await this.customers.getCheckoutProfile(command.userId);
    if (!customer || customer.isSuspended) {
      throw new BadRequestException('Customer account is not eligible for checkout');
    }

    // 2. Compute Pricing via Pure Domain Policy
    const productIds = command.items.map((i) => i.productId);
    const unitPrices = await this.catalog.getUnitPricesCents(productIds);
    const totalCents = this.pricingPolicy.calculateTotalCents(
      command.items,
      unitPrices,
      customer.loyaltyTier
    );

    // 3. Create Pending Order & Reserve Inventory BEFORE charging external payment
    const pendingOrder = await this.orders.createPendingOrder(customer.userId, totalCents);
    const reserved = await this.inventory.reserveStock(pendingOrder.orderId, command.items);
    if (!reserved) {
      await this.orders.markOrderFailed(pendingOrder.orderId, 'INSUFFICIENT_INVENTORY');
      throw new BadRequestException('One or more items are out of stock');
    }

    // 4. Execute Polymorphic Payment Strategy with Compensating Rollback on Failure
    try {
      const paymentResult = await strategy.charge({
        orderId: pendingOrder.orderId,
        userId: customer.userId,
        amountCents: totalCents,
        paymentToken: command.paymentToken,
      });

      await this.inventory.commitReservation(pendingOrder.orderId);
      await this.orders.markOrderCompleted(pendingOrder.orderId, paymentResult.transactionId);

      // 5. Emit Decoupled Event (SMTP failure never aborts a completed payment!)
      this.eventBus.emit(
        'order.completed',
        new OrderCompletedDomainEvent(
          pendingOrder.orderId,
          customer.userId,
          customer.email,
          totalCents,
          paymentResult.transactionId
        )
      );

      return {
        orderId: pendingOrder.orderId,
        totalCents,
        transactionId: paymentResult.transactionId,
      };
    } catch (paymentError) {
      await this.inventory.releaseReservation(pendingOrder.orderId, command.items);
      await this.orders.markOrderFailed(pendingOrder.orderId, 'PAYMENT_DECLINED');
      throw paymentError;
    }
  }
}
```

