// src/features/checkout/CheckoutContainer.tsx
import React, { useState } from 'react';
import { PaymentCheckoutHost } from '../payment/PaymentCheckoutHost';
import { PaymentMethodPlugin, PaymentSubmissionPayload } from '../payment/payment-plugin.contract';
import { UserAvatarBadge, UserAvatarBadgeProps } from '../users/UserAvatarBadge';

export interface CheckoutCartLineItem {
  readonly productId: string;
  readonly productName: string;
  readonly unitPriceCents: number;
  readonly quantity: number;
}

export interface CheckoutServiceClientPort {
  submitCheckout(payload: {
    userId: string;
    items: ReadonlyArray<{ productId: string; quantity: number }>;
    paymentProvider: string;
    paymentToken: string;
  }): Promise<{ orderId: string; totalCents: number; transactionId: string }>;
}

export interface CheckoutContainerProps {
  readonly userSummary: UserAvatarBadgeProps & { readonly userId: string };
  readonly items: readonly CheckoutCartLineItem[];
  readonly paymentPlugins: readonly PaymentMethodPlugin[];
  readonly checkoutClient: CheckoutServiceClientPort;
}

export const CheckoutContainer: React.FC<CheckoutContainerProps> = ({
  userSummary,
  items,
  paymentPlugins,
  checkoutClient,
}) => {
  const [selectedProvider, setSelectedProvider] = useState(paymentPlugins[0]?.type ?? 'CREDIT_CARD');
  const [receipt, setReceipt] = useState<{ orderId: string; transactionId: string } | null>(null);
  const [error, setError] = useState<string | null>(null);

  const subtotalCents = items.reduce((sum, item) => sum + item.unitPriceCents * item.quantity, 0);

  const handlePaymentSubmitted = async (paymentPayload: PaymentSubmissionPayload) => {
    setError(null);
    try {
      const res = await checkoutClient.submitCheckout({
        userId: userSummary.userId,
        items: items.map((i) => ({ productId: i.productId, quantity: i.quantity })),
        paymentProvider: paymentPayload.type,
        paymentToken: String(paymentPayload.details.token ?? 'tok_verified'),
      });
      setReceipt({ orderId: res.orderId, transactionId: res.transactionId });
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Checkout failed');
    }
  };

  if (receipt) {
    return (
      <div role="status" className="p-6 bg-green-50 rounded">
        <h3>Order Confirmed: #{receipt.orderId}</h3>
        <p>Transaction Reference: {receipt.transactionId}</p>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <header className="flex justify-between items-center">
        <h2 className="text-2xl font-bold">Checkout</h2>
        {/* ISP in action: UserAvatarBadge only receives narrow primitive props */}
        <UserAvatarBadge
          firstName={userSummary.firstName}
          lastName={userSummary.lastName}
          avatarUrl={userSummary.avatarUrl}
        />
      </header>

      {error && <div role="alert" className="p-3 bg-red-100 text-red-700">{error}</div>}

      <div className="flex gap-2">
        {paymentPlugins.map((plugin) => (
          <button
            key={plugin.type}
            type="button"
            onClick={() => setSelectedProvider(plugin.type)}
            className={selectedProvider === plugin.type ? 'font-bold underline' : ''}
          >
            {plugin.displayName}
          </button>
        ))}
      </div>

      {/* OCP in action: PaymentCheckoutHost renders any registered plugin without modification */}
      <PaymentCheckoutHost
        plugins={paymentPlugins}
        selectedType={selectedProvider}
        amountCents={subtotalCents}
        onSubmit={handlePaymentSubmitted}
      />
    </div>
  );
};
