  width: 28px;
  height: 28px;
  border-radius: 8px;
  background: #dbeafe;
  color: #1e40af;
  font-size: 15px;
  font-weight: 700;
  user-select: none;
}

.diagram-wrapper > h4,
.diagram-wrapper > h3,
.diagram-wrapper > h2,
