/* ==========================================================================
   ENHANCED ARCHITECTURE BLUEPRINT CANVAS & ACTUAL MERMAID VIEW
   ========================================================================== */
.mermaid,
.mermaid-container,
.mermaid-view {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 100%;
  min-height: 290px;
  height: auto;
  overflow: hidden;
  padding: 0;
  background-color: #fafbfc;
  background-image: 
    radial-gradient(#cbd5e1 1.25px, transparent 1.25px),
    linear-gradient(to bottom, rgba(255, 255, 255, 0.7) 0%, transparent 100%);
  background-size: 20px 20px, 100% 100%;
  border-radius: 14px;
  box-shadow: inset 0 2px 8px rgba(0, 0, 0, 0.02);
  user-select: none;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Inter", "Plus Jakarta Sans", sans-serif !important;
  transition: background-color 0.25s ease, border-color 0.2s ease;
}

/* Reset .mermaid if nested inside container or viewport to avoid double boxes */
.mermaid-container .mermaid,
.mermaid-viewport .mermaid,
.mermaid-canvas .mermaid,
.diagram-wrapper .mermaid {
  background: transparent !important;
  background-color: transparent !important;
  background-image: none !important;
  box-shadow: none !important;
  border: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  margin: 0 auto !important;
  min-height: auto !important;
  width: 100% !important;
}

.mermaid-viewport {
  position: relative;
  width: 100%;
  min-height: 290px;
  height: auto;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: grab;
  user-select: none;
  box-sizing: border-box;
  padding: 32px 20px;
  touch-action: none;
}

.mermaid-viewport:active,
.mermaid-viewport.is-grabbing,
.mermaid-container.is-grabbing,
.mermaid-view.is-grabbing,
.mermaid.is-grabbing {
  cursor: grabbing !important;
}

.mermaid-canvas {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transform-origin: center center;
  will-change: transform;
  transition: transform 0.05s ease-out;
}

@media (prefers-color-scheme: dark-disabled-for-notes) {
  .mermaid,
  .mermaid-container,
  .mermaid-view {
    background-color: #0b0f19;
    background-image: 
      radial-gradient(#334155 1.25px, transparent 1.25px),
      linear-gradient(to bottom, rgba(15, 23, 42, 0.6) 0%, transparent 100%);
    box-shadow: inset 0 2px 8px rgba(0, 0, 0, 0.3);
  }
}

