    background: repeating-linear-gradient(
      to bottom,
      #475569 0px,
      #475569 5px,
      transparent 5px,
      transparent 10px
    );
  }
}

.pipe-arrow::after {
  content: '↓';
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: #ffffff;
  border: 2px solid #cbd5e1;
  color: #2563eb;
  font-size: 15px;
  font-weight: 800;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  font-family: system-ui, sans-serif;
  line-height: 1;
}

