/* Connecting Arrow Connector between Pipe Nodes */
.pipe-arrow {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: flex-start;
  height: 44px;
  margin: -1px 0;
  padding-left: 29px; /* Centers with badge (22px padding + 22px half-width = 44px) */
  z-index: 1;
  font-size: 0; /* Hide raw unstyled text */
  user-select: none;
}

.pipe-arrow::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: 44px;
  width: 2px;
  background: repeating-linear-gradient(
    to bottom,
    #94a3b8 0px,
    #94a3b8 5px,
    transparent 5px,
    transparent 10px
  );
  z-index: 1;
}

@media (prefers-color-scheme: dark-disabled-for-notes) {
  .pipe-arrow::before {
    background: repeating-linear-gradient(
      to bottom,
      #475569 0px,
      #475569 5px,
      transparent 5px,
      transparent 10px
    );
  }
}

.pipe-arrow::after {
  content: '↓';
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: #ffffff;
  border: 2px solid #cbd5e1;
  color: #2563eb;
  font-size: 15px;
  font-weight: 800;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.08);
  font-family: system-ui, sans-serif;
  line-height: 1;
}

@media (prefers-color-scheme: dark-disabled-for-notes) {
  .pipe-arrow::after {
    background: #0f172a;
    border-color: #475569;
    color: #60a5fa;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
  }
}

